upstream api_upstream {
    server 10.0.4.21:8080;
}

server {
    listen 443 ssl;
    server_name api.campus.test;
    ssl_certificate /etc/letsencrypt/live/api.campus.test/fullchain.pem;
    ssl_certificate_key /etc/letsencrypt/live/api.campus.test/privkey.pem;

    location / {
        proxy_pass http://api_upstream;
        proxy_set_header Host $host;
        proxy_read_timeout 600s;
    }

    location = /health {
        return 200 "ok";
    }
}
